--
-- Table structure for table `horario`
--

DROP TABLE IF EXISTS `horario`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `horario` (
  `id` int NOT NULL AUTO_INCREMENT,
  `trabajador_id` int NOT NULL,
  `fecha` date NOT NULL,
  `hora_inicio` time NOT NULL,
  `hora_fin` time NOT NULL,
  `festivo` tinyint(1) DEFAULT '0',
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `proyecto_nombre` varchar(255) DEFAULT NULL,
  `vacaciones` tinyint(1) DEFAULT '0',
  `bajamedica` tinyint(1) DEFAULT '0',
  `dianegativo` tinyint(1) DEFAULT '0',
  `horanegativa` decimal(5,2) DEFAULT '0.00',
  `pagada` tinyint(1) DEFAULT '0',
  `horas_pagadas` decimal(6,2) DEFAULT '0.00',
  `tipo_horas_pagadas` varchar(255) DEFAULT NULL,
  `empresa` varchar(255) DEFAULT NULL,
  `empresa_id` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `trabajador_id` (`trabajador_id`),
  KEY `idx_horario_empresa_fecha` (`empresa_id`,`fecha`),
  KEY `idx_horario_trabajador_fecha` (`trabajador_id`,`fecha`),
  CONSTRAINT `horario_ibfk_93` FOREIGN KEY (`trabajador_id`) REFERENCES `trabajador` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `horario_ibfk_94` FOREIGN KEY (`empresa_id`) REFERENCES `empresa` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=19324 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

